from pathlib import Path
import json, html, sys, shutil, re
from seo import prepare, finish, EXCLUDED, BASE
from local_content import MOVING, related, HOME_ANSWERS
PRODUCTION = "--production" in sys.argv
ROUTES = []

ROOT = Path(__file__).resolve().parents[1]/'outputs'/'nobleton-site'
if PRODUCTION:
    preview_root=ROOT
    ROOT=ROOT.parent/'nobleton-production'
    ROOT.mkdir(exist_ok=True)
    shutil.copytree(preview_root/'assets',ROOT/'assets',dirs_exist_ok=True)
    shutil.copy2(preview_root/'favicon.svg',ROOT/'favicon.svg')

def write(path, text):
    p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text)

resources = [
 {'slug':'nobleton-public-school','name':'Nobleton Public School','category':'Schools','description':'Public school information, school news and family resources from the York Region District School Board.','url':'https://nobleton-ps.yrdsb.ca/','detail':'Visit the school’s official website for current announcements and contact information. Confirm enrolment eligibility and attendance boundaries directly with the school board.'},
 {'slug':'st-mary-catholic-elementary-school','name':'St. Mary Catholic Elementary School','category':'Schools','description':'Catholic elementary education and school information for families in Nobleton.','url':'https://smy.ycdsb.ca/contact/','detail':'Located at 75 Greenside Drive, Nobleton. Contact the school or York Catholic District School Board for enrolment requirements and current attendance boundaries.'},
 {'slug':'nobleton-library','name':'Nobleton Library','category':'Community','description':'Your local branch for library services, reading and community discovery.','url':'https://www.kinglibrary.ca/hours-locations','detail':'The Nobleton branch is located at 8 Sheardown Drive. Check the library’s official website for current hours, holiday closures and available services.'},
 {'slug':'nobleton-community-park','name':'Nobleton Community Park','category':'Parks & recreation','description':'A local outdoor destination with play areas and sports amenities on Old King Road.','url':'https://www.king.ca/recreation-living/parks-trails-and-forestry/parks/nobleton-community-park','detail':'Located at 15 Old King Road. King Township lists playground and sports amenities at this park. Check the Township website for current access, seasonal availability and facility information.'},
 {'slug':'king-chamber','name':'King Chamber of Commerce','category':'Business resources','description':'Connections and resources for businesses across King Township, including Nobleton.','url':'https://www.kingchamber.ca/','detail':'The Chamber serves the broader King business community. Visit its website for membership information and current business events.'},
]
icons={'Schools':'▤','Community':'⌂','Parks & recreation':'♧','Business resources':'↗','Home services':'⌁','Food & drink':'◒','Health & wellness':'✳','Shopping':'◇'}
def card(r):
 return f'''<a class="listing" href="/directory/{r['slug']}/" data-category="{r['category']}" data-search="{html.escape((r['name']+' '+r['description']+' '+r['category']).lower())}"><span class="listing-icon" aria-hidden="true">{icons[r['category']]}</span><span class="eyebrow">{r['category']}</span><h3>{r['name']}</h3><p>{r['description']}</p><span class="card-foot">Public information <span aria-hidden="true">↗</span></span></a>'''
def photo(name,alt,caption,extra='',eager=False):
 return f'<figure class="editorial-photo {extra}"><img src="/assets/images/{name}.jpg" srcset="/assets/images/{name}-768.jpg 768w, /assets/images/{name}.jpg 1536w" sizes="(max-width: 780px) 100vw, 50vw" alt="{alt}" width="1536" height="1024" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=high" if eager else ""}><figcaption>{caption}</figcaption></figure>'

def enrich(body,path):
 street=('village-street','AI-generated illustration of a leafy village main street with brick shops and a café','AI-generated village inspiration')
 park=('village-park','AI-generated illustration of a tree-lined park path and benches','AI-generated countryside inspiration')
 home=('limestone-home','AI-generated luxury limestone country house with landscaped gardens','AI-generated home inspiration · Not a listing')
 terrace=('garden-residence','AI-generated luxury home with a timber-covered garden terrace','AI-generated home inspiration · Not a listing')
 if path=='/' and '<div class="hero-art">' in body:
  start=body.index('<div class="hero-art">'); end=body.index('</section>',start)
  body=body[:start]+'<div class="hero-art photo-hero">'+photo(*street,eager=True)+'<div class="art-caption"><span class="compass" aria-hidden="true">✳</span><span>Small-town roots.<br><strong>Room to discover.</strong></span></div></div>'+body[end:]
  body=body.replace('<div class="guide-links">',photo(*park,extra='guide-photo')+'<div class="guide-links">')
  body=body.replace('<article class="estate-feature">','<article class="estate-feature image-feature">'+photo(*home))
  body=body.replace('<article class="service-feature">','<article class="service-feature image-feature">'+photo(*terrace))
  body=body.replace('<div class="house-line" aria-hidden="true">⌂</div>','')
 elif path in ['/directory/','/guide/','/real-estate/','/find-a-service/','/submit/','/about/']:
  asset={'/directory/':street,'/guide/':park,'/real-estate/':home,'/find-a-service/':terrace,'/submit/':street,'/about/':street}[path]
  body=body.replace('<section class="page-intro">','<section class="page-intro visual-intro">',1)
  body=body.replace('</div></section>',photo(*asset,extra='intro-photo',eager=True)+'</div></section>',1)
  if path=='/real-estate/':
   body+='<section class="wrap section residence-story">'+photo(*terrace)+'<div><p class="eyebrow">ROOM TO MAKE IT YOURS</p><h2>A little more space.<br>A little closer to nature.</h2><p>Explore the community beyond the front door, from everyday essentials to places to unwind.</p><a class="text-link" href="/guide/">Discover life in Nobleton ↗</a></div></section>'
 elif path in ['/guide/parks/','/guide/essentials/']:
  body=body.replace('<article class="wrap reading section">','<article class="wrap reading section">'+photo(*(park if 'parks' in path else street),extra='article-photo'))
 return body

def layout(title,desc,body,path='/',active=''):
 if path=='/': body+=HOME_ANSWERS
 if path.startswith('/guide/') and path!='/guide/': body=body.replace('</article>',related()+'</article>')
 if path.startswith('/guide/') and path!='/guide/':
  headings=[]
  def anchor(m):
   label=m.group(1); ident='section-'+str(len(headings)+1); headings.append((ident,label)); return f'<h2 id="{ident}">{label}</h2>'
  body=re.sub(r'<h2>(.*?)</h2>',anchor,body)
  toc='<aside class="article-toc" aria-label="On this page"><h2>On this page</h2><ul>'+''.join(f'<li><a href="#{i}">{t}</a></li>' for i,t in headings)+'</ul></aside>'
  body=body.replace('<article class="wrap reading section">','<article class="wrap reading section">'+toc)
 body=enrich(body,path)
 title,desc,body,schema=prepare(title,desc,body,path,resources)
 ROUTES.append(path)
 robots='index,follow,max-image-preview:large' if PRODUCTION and path not in EXCLUDED else 'noindex,follow'
 preview_label='Independent local guide' if PRODUCTION else 'Community preview'
 nav=''.join(f'<a href="{u}"'+(' aria-current="page"' if active==k else '')+f'>{k}</a>' for k,u in [('Directory','/directory/'),('Local guide','/guide/'),('Real estate','/real-estate/'),('Find a service','/find-a-service/')])

 return f'''<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Nobleton</title><meta name="description" content="{html.escape(desc)}"><meta name="robots" content="{robots}"><meta name="theme-color" content="#1e493d"><link rel="canonical" href="{BASE}{path}"><meta property="og:title" content="{html.escape(title)} | Nobleton"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:type" content="website"><meta property="og:site_name" content="Nobleton"><meta property="og:locale" content="en_CA"><meta property="og:image" content="{BASE}/assets/images/village-street.jpg"><meta property="og:image:alt" content="AI-generated village inspiration for the independent Nobleton guide"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{html.escape(title)} | Nobleton"><meta name="twitter:description" content="{html.escape(desc)}"><meta name="twitter:image" content="{BASE}/assets/images/village-street.jpg"><meta property="og:url" content="{BASE}{path}"><link rel="icon" href="/favicon.svg?v=2" type="image/svg+xml" sizes="any"><link rel="stylesheet" href="/assets/style.css"><link rel="stylesheet" href="/assets/imagery.css"><script type="application/ld+json">{json.dumps(schema)}</script><script src="/assets/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="topline"><span>NOBLETON, ONTARIO</span><span>A little closer to home.</span><span class="preview">{preview_label}</span></div><header><a class="brand" href="/" aria-label="Nobleton.ca home">Nobleton</a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Main navigation">{nav}<a class="button small" href="/submit/">Add your business <span aria-hidden="true">↗</span></a></nav></header><main id="main">{body}</main><footer><div class="footer-top"><div><a class="brand" href="/" aria-label="Nobleton.ca home">Nobleton</a><p>Your place to find your people.<br>An independent guide to Nobleton, Ontario.</p></div><div><h2>Explore</h2><a href="/directory/">Local directory</a><a href="/guide/">Living in Nobleton</a><a href="/real-estate/">Real estate</a></div><div><h2>Get involved</h2><a href="/submit/">Add or update a listing</a><a href="/find-a-service/">Request a service</a><a href="mailto:info@nobleton.ca">info@nobleton.ca</a></div><div><h2>About this guide</h2><a href="/about/">Our approach</a><a href="/standards/">Listing standards</a><a href="/privacy/">Privacy & contact</a></div></div><div class="footer-bottom"><span>© 2026 Nobleton.ca</span><span>Independent community website. Not affiliated with the Township of King.</span></div></footer></body></html>'''
def page(slug,title,desc,body,active=''):
 write((slug+'/index.html').lstrip('/'),layout(title,desc,body,'/'+slug.strip('/')+'/',active))
def intro(kicker,title,desc):
 return f'<section class="page-intro"><div class="wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></div></section>'

categories=[('Schools','Schools'),('Community','Library & community'),('Parks & recreation','Parks & recreation'),('Business resources','Business resources')]
cats=''.join(f'<a class="category" href="/directory/?category={html.escape(__import__("urllib.parse",fromlist=["quote"]).quote(c))}"><span aria-hidden="true">{icons[c]}</span><strong>{label}</strong><span class="arrow" aria-hidden="true">↗</span></a>' for c,label in categories)
home=f'''<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="dot"></span> NOBLETON, ONTARIO · YOUR LOCAL GUIDE</p><h1>Your guide to<br><em>Nobleton.</em><br>Feel right at home.</h1><p>Find local businesses, explore the area, and feel a little more at home in Nobleton.</p><form class="search" action="/directory/" role="search"><label class="sr-only" for="home-search">Search the local directory</label><span aria-hidden="true">⌕</span><input id="home-search" name="q" placeholder="What are you looking for?" type="search"><button type="submit">Explore <span aria-hidden="true">↗</span></button></form><div class="popular">Start with <a href="/directory/?category=Schools">Schools</a><a href="/guide/parks/">Parks & recreation</a><a href="/real-estate/">A place to call home</a></div></div><div class="hero-art"><img src="/assets/landscape.svg" alt="Original illustration of rolling green hills and a village, inspired by the countryside"><div class="art-caption"><span class="compass" aria-hidden="true">✳</span><span>Small-town roots.<br><strong>Room to discover.</strong></span><span class="art-location">KING TOWNSHIP<br>ONTARIO</span></div></div></section>
<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">KEEP IT LOCAL</p><h2>Start with what’s nearby.</h2></div><a class="text-link" href="/directory/">Explore the directory <span aria-hidden="true">↗</span></a></div><div class="categories">{cats}</div></section>
<section class="guide-band"><div class="wrap guide-split"><div><p class="eyebrow">GET TO KNOW NOBLETON</p><h2>A village to explore.<br>A community to belong to.</h2><p>New here or here for years? Find the everyday essentials and places that bring the community together.</p><a class="button light" href="/guide/">Your local guide <span aria-hidden="true">↗</span></a></div><div class="guide-links"><a href="/guide/schools/"><span>01</span><div><h3>Schools & families</h3><p>Start with local schools and official resources.</p></div>↗</a><a href="/guide/parks/"><span>02</span><div><h3>Outside & around town</h3><p>Parks, library visits and ways to spend the day.</p></div>↗</a><a href="/guide/essentials/"><span>03</span><div><h3>The everyday essentials</h3><p>Find municipal services and community information.</p></div>↗</a></div></div></section>
<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">A FEW PLACES TO START</p><h2>Part of the neighbourhood.</h2></div><a class="text-link" href="/directory/">All directory entries ↗</a></div><div class="cards">{''.join(card(r) for r in [resources[2],resources[0],resources[3]])}</div><p class="fine">Public-resource entries link to official sources. Inclusion does not imply a partnership or endorsement.</p></section>
<section class="wrap feature-pair"><article class="estate-feature"><p class="eyebrow">PUT DOWN ROOTS</p><h2>Your next chapter<br>could start here.</h2><p>Explore life in Nobleton. Local real-estate listings are coming with our brokerage partner.</p><a class="text-link" href="/real-estate/">Explore real estate ↗</a><div class="house-line" aria-hidden="true">⌂</div></article><article class="service-feature"><p class="eyebrow">A HAND AROUND HOME</p><h2>Tell us what<br>you’re looking for.</h2><p>We’re building a network of local providers. Share your service request to help us connect the community.</p><a class="text-link" href="/find-a-service/">Request a local service ↗</a></article></section>
<section class="wrap join"><div><p class="eyebrow">LOCAL BUSINESS OWNER?</p><h2>You belong here, too.</h2><p>Help neighbours discover what you do. Business submissions are free at launch.</p></div><a class="button" href="/submit/">Add your business — free ↗</a></section>'''
write('index.html',layout('Discover local businesses & life in Nobleton','An independent Nobleton community guide. Discover local resources, submit your business, explore real estate and request local services.',home))

allcats=['All categories']+list(icons.keys())
options=''.join(f'<option>{c}</option>' for c in allcats)
page('directory','Local directory','Find schools, community resources and local business categories in Nobleton.',intro('FIND YOUR LOCAL','Nobleton business & community directory.','Explore community resources and help us grow a directory of businesses serving Nobleton.')+f'''<section class="wrap section"><form class="directory-filter" role="search"><div><label for="directory-search">Search the directory</label><input type="search" id="directory-search" name="q" placeholder="Name, service or keyword"></div><div><label for="category">Category</label><select id="category" name="category">{options}</select></div><button class="button" type="submit">Search ↗</button><button class="filter-reset" type="reset">Clear filters</button></form><noscript><p>All entries are shown below. Enable JavaScript to filter the directory.</p></noscript><p id="result-count" role="status" aria-live="polite">5 public-resource entries</p><div class="cards" id="directory-results">{''.join(card(r) for r in resources)}</div><div id="empty-state" class="empty" hidden><p class="eyebrow">LET’S BUILD THIS TOGETHER</p><h2>No matching entries yet.</h2><p><a class="text-link" href="/directory/">View all directory entries ↗</a></p><p>Our directory is just getting started. Try another search, add your business, or tell us which service you need.</p><a class="button" href="/submit/">Submit a free listing ↗</a> <a class="text-link" href="/find-a-service/">Request a service ↗</a></div><aside class="note"><strong>A directory built on clear information.</strong><p>These initial public-resource entries are sourced from official websites. Commercial listings will be reviewed before publication. No paid placements are currently offered.</p></aside></section>''','Directory')
for r in resources:
 page('directory/'+r['slug'],r['name'],r['description'],intro(r['category'],r['name'],r['description'])+f'''<section class="wrap reading section"><a class="text-link" href="/directory/">← Back to the directory</a><h2>At a glance</h2><p>{r['detail']}</p><a class="button" href="{r['url']}">Visit official website ↗</a><aside class="note"><p>Public information entry · Source checked September 7, 2026.</p><p>This organization is not a confirmed Nobleton.ca partner. Please confirm current details directly.</p></aside><a class="text-link" href="/submit/?type=correction">Suggest a correction ↗</a></section>''','Directory')

guides=[('schools','Schools in Nobleton','Find local schools and the official sources to help with your next steps.'),('parks','Nobleton parks, recreation & library','Places to play, read and explore in and around the village.'),('essentials','Living in Nobleton','Start here for municipal information and everyday community resources.'),('moving-to-nobleton','Moving to Nobleton','A practical checklist for schools, local amenities and service planning.')]
page('guide','Your local guide','Explore schools, parks, library services and everyday information for life in Nobleton.',intro('FEEL AT HOME','Your guide to living in Nobleton.','A practical starting point for living in Nobleton, whether you’re settling in or discovering something new.')+'<section class="wrap section cards">'+''.join(f'<a class="listing guide-card" href="/guide/{s}/"><span class="eyebrow">THE LOCAL GUIDE · 0{i+1}</span><h2>{t}</h2><p>{d}</p><span class="text-link">Explore the guide ↗</span></a>' for i,(s,t,d) in enumerate(guides))+'</section>','Local guide')
guide_content={
'schools':f'''<h2>Which schools can I explore in Nobleton?</h2><p>Nobleton Public School and St. Mary Catholic Elementary School provide official information for local families. Start with the school websites, then check eligibility and attendance boundaries with the relevant school board.</p><h3>Nobleton Public School</h3><p>Find current school information through the York Region District School Board.</p><a class="text-link" href="{resources[0]['url']}">Visit Nobleton Public School ↗</a><h3>St. Mary Catholic Elementary School</h3><p>The school’s contact page lists its address as 75 Greenside Drive, Nobleton.</p><a class="text-link" href="{resources[1]['url']}">Visit St. Mary’s contact page ↗</a><h2>Before you choose a home or register</h2><p>Confirm address-specific attendance boundaries, admission requirements, transportation eligibility and registration dates directly with the board. A nearby school is not a guarantee of admission.</p>''',
'parks':f'''<h2>Where can I spend time outdoors in Nobleton?</h2><p>Nobleton Community Park, at 15 Old King Road, is a starting point for outdoor recreation. The Township lists a playground and sports amenities; check current access and seasonal availability before your visit.</p><a class="text-link" href="{resources[3]['url']}">Park information from King Township ↗</a><h2>Where is the Nobleton library?</h2><p>The Nobleton branch of King Township Public Library is at 8 Sheardown Drive. Its official website provides current hours and library information.</p><a class="text-link" href="{resources[2]['url']}">Library locations & hours ↗</a><h2>What’s happening in the community?</h2><p>For upcoming Township events and schedules, check the official events page. Dates and arrangements can change.</p><a class="text-link" href="https://www.king.ca/events">Explore King Township events ↗</a>''',
'essentials':'''<h2>Where is Nobleton?</h2><p>Nobleton is a community in the southwest of King Township, Ontario. This guide focuses on Nobleton, while linking to Township-wide resources where they serve local residents.</p><a class="text-link" href="https://www.king.ca/OurCommunity/nobleton">Nobleton on the Township website ↗</a><h2>Where do I find municipal information?</h2><p>King Township’s official website is the source for municipal services, notices and community information. Nobleton.ca is an independent community guide and does not provide municipal services.</p><a class="text-link" href="https://www.king.ca/">Visit King Township ↗</a><h2>Where can local businesses connect?</h2><p>The King Chamber of Commerce serves businesses across the Township. Visit its website for current membership and event information.</p><a class="text-link" href="https://www.kingchamber.ca/">Visit the King Chamber ↗</a>'''
}
guide_content['moving-to-nobleton']=MOVING
for s,t,d in guides:
 page('guide/'+s,t,d,intro('YOUR LOCAL GUIDE',t,d)+f'<article class="wrap reading section"><a class="text-link" href="/guide/">← All guides</a>{guide_content[s]}<p class="fine">Sources linked above · Reviewed September 7, 2026.</p><aside class="note">Something changed? Email <a href="mailto:info@nobleton.ca">info@nobleton.ca</a> with the official source so we can review an update.</aside></article>','Local guide')

page('real-estate','Real estate in Nobleton','Explore life in Nobleton and learn about upcoming local real-estate listings.',intro('A PLACE TO CALL HOME','Make your next chapter a local one.','Get to know Nobleton while we prepare our real-estate section with our brokerage partner.')+'''<section class="wrap section feature-pair"><article class="estate-feature"><p class="eyebrow">REAL ESTATE · COMING SOON</p><h2>Local listings.<br>A clearer view.</h2><p>Property listings will appear here once our partner’s details and approved listing source are ready.</p><p>No properties are currently advertised on Nobleton.ca.</p><a class="button" href="mailto:info@nobleton.ca?subject=Nobleton%20real-estate%20inquiry">Email a real-estate inquiry ↗</a></article><article class="reading"><h2>Start with the neighbourhood.</h2><p>Explore the practical details that help a place feel like home.</p><div class="stack-links"><a href="/guide/schools/">Schools & family resources ↗</a><a href="/guide/parks/">Parks, recreation & the library ↗</a><a href="/guide/essentials/">Living in Nobleton ↗</a></div><p class="fine">Inquiries go to the Nobleton.ca team. We will confirm the partner and ask before sharing your details.</p></article></section>''','Real estate')

def form(kind):
 business=kind=='business'
 fields='''<label for="business">Business or organization name</label><input id="business" name="Business" required maxlength="120"><label for="website">Website (optional)</label><input id="website" name="Website" type="url" placeholder="https://" maxlength="250"><label for="service-area">Service area</label><input id="service-area" name="Service area" required placeholder="Nobleton, or areas you serve" maxlength="180">''' if business else '''<label for="area">Your area</label><input id="area" name="Area" required placeholder="Nobleton or nearby community" maxlength="120">'''
 return f'''<form class="email-form" data-kind="{kind}"><label for="name">Your name</label><input id="name" name="Name" autocomplete="name" required maxlength="100"><label for="email">Email address</label><input id="email" name="Email" type="email" autocomplete="email" required maxlength="180">{fields}<label for="request-category">{'Listing category' if business else 'Service needed'}</label><select id="request-category" name="Category" required><option value="">Choose a category</option>{''.join(f'<option>{c}</option>' for c in list(icons)+['Other'])}</select><label for="details">{'About your business, or details to correct' if business else 'How can we help?'}</label><textarea id="details" name="Details" rows="5" maxlength="1500" required placeholder="{'Tell us what you offer and where people can find you.' if business else 'Describe the service and approximate timing. Please leave out sensitive details.'}"></textarea><label class="check"><input type="checkbox" required name="Contact permission" value="Yes"><span>I agree that Nobleton.ca may contact me about this {'submission' if business else 'request'}. My details will not be shared with a provider without my permission.</span></label><p class="fine">This preview prepares an email to info@nobleton.ca. You review and send it in your email app. Nothing is submitted automatically. <a href="/privacy/">Privacy information</a></p><button class="button" type="submit">Prepare email draft ↗</button><div class="draft-output" hidden><p role="status">Your draft is ready. Open your email app, review the message, then send it.</p><a class="button open-email">Open email app ↗</a><label for="draft-text">Or copy your draft and email info@nobleton.ca</label><textarea id="draft-text" readonly rows="8"></textarea><button class="copy-draft" type="button">Copy draft</button><p class="copy-status" role="status"></p></div></form>'''
page('submit','Add your business for free','Submit a free business listing or suggest a correction to the Nobleton directory.',intro('GROW WITH THE COMMUNITY','Let’s put your business on the local map.','Free submissions at launch. Tell us about your business or suggest an update to an existing entry.')+'<section class="wrap section form-layout"><aside><h2>A good introduction starts here.</h2><p>We welcome businesses based in Nobleton and providers that clearly serve the area.</p><ol><li>Tell us what you do.</li><li>We review your details.</li><li>We contact you if anything needs clarification.</li></ol><p>Submitting a listing does not guarantee publication. Please submit only details you’re authorized to share.</p><a class="text-link" href="/standards/">Read our listing standards ↗</a></aside>'+form('business')+'</section>')
page('find-a-service','Find a local service','Share a service request with Nobleton.ca as we build our local provider network.',intro('LOCAL HELP STARTS HERE','What can the neighbourhood help you with?','Tell us what you need. We’re building our provider network and will let you know whether a suitable connection is available.')+'<section class="wrap section form-layout"><aside><h2>One request.<br>A local starting point.</h2><p>Share the type of service, your area and approximate timing. The Nobleton.ca team reviews inquiries manually.</p><p>Our network is at an early stage. A match or response time is not guaranteed.</p><p>We’ll ask before passing your contact details to a provider. You choose whether to proceed and agree any pricing directly.</p><p class="fine">For emergencies, contact the appropriate emergency service directly.</p></aside>'+form('service')+'</section>','Find a service')

page('about','About Nobleton.ca','An independent local guide connecting Nobleton residents, businesses and community information.',intro('SMALL-TOWN ROOTS','A more connected Nobleton.','A local starting point for the places, people and practical information around you.')+'''<article class="wrap reading section"><h2>Built for everyday local life</h2><p>Nobleton.ca brings together a community directory, sourced local guides, a developing service-referral network and an upcoming real-estate section.</p><h2>Free to get started</h2><p>Our launch is focused on building useful local coverage. Business submissions are free. If paid placements or referral arrangements are introduced later, they will be clearly disclosed.</p><h2>Independent and transparent</h2><p>We are not affiliated with the Township of King, local schools or organizations listed in public-resource entries. Their official websites remain the source for current service and enrolment information.</p><h2>Help shape the guide</h2><p>Recommend a resource, suggest a correction or ask a question at <a href="mailto:info@nobleton.ca">info@nobleton.ca</a>.</p></article>''')
page('standards','Listing standards','How Nobleton.ca reviews directory submissions and presents local information.',intro('CLEAR INFORMATION','A useful directory starts with trust.','Our approach to submissions, corrections and local coverage.')+'''<article class="wrap reading section"><h2>Local relevance</h2><p>Entries should be based in Nobleton or clearly serve its residents. Nearby providers must state their actual location and service area.</p><h2>Accurate details</h2><p>Submit your real business name, contact information, website and an accurate description. Claims about qualifications or credentials need supporting information. We do not publish invented ratings, testimonials or guarantees.</p><h2>Review and corrections</h2><p>We review submissions before publication and may ask for clarification. Public-resource entries cite official sources. To request a correction or removal, email info@nobleton.ca with the entry and relevant details.</p><h2>Clear relationships</h2><p>A listing is not an endorsement or a guarantee of service. Public-resource entries are distinguished from partnerships. Submissions are free at launch; future sponsored placements will be labelled.</p></article>''')
page('privacy','Privacy & contact','How Nobleton.ca handles email drafts and contact information.',intro('PRIVACY & CONTACT','You choose what to share.','Contact the Nobleton.ca team at info@nobleton.ca.')+'''<article class="wrap reading section"><h2>How the preview works</h2><p>Forms prepare an email draft in your browser. They do not send form contents to a server or store them in browser storage. You decide whether to open your email app and send the draft. Copying uses your device clipboard only when you select “Copy draft.”</p><h2>Email inquiries</h2><p>If you send an email, its contents and your email address are delivered through your email provider to info@nobleton.ca. We use inquiries to respond to the relevant request. We ask before sharing personal contact details with a service provider.</p><h2>Analytics and external links</h2><p>This preview does not load third-party analytics, advertising scripts or embedded real-estate feeds. External websites have their own privacy practices. The preview web server may record technical requests in its access log.</p><h2>Questions or corrections</h2><p>Email <a href="mailto:info@nobleton.ca">info@nobleton.ca</a> about your information or a directory correction.</p><p class="fine">Preview notice · September 7, 2026. This notice must be reviewed when live forms, hosting or listing integrations are connected.</p></article>''')
write('404.html',layout('Page not found','Return to the Nobleton community guide.',intro('404','Let’s get you back to the neighbourhood.','This page could not be found.')+'<div class="wrap section"><a class="button" href="/">Back to home ↗</a></div>',path='/404.html'))
finish(ROOT,ROUTES,PRODUCTION)
print('Built',len(list(ROOT.rglob('*.html'))),'HTML pages')
